import type { UIMessage } from "@tanstack/ai-react";
import { useSyncExternalStore } from "react";

export interface ChatScope {
   environment: string;
   package: string;
}

/** One saved conversation from the Ask window. */
export interface ChatThread {
   id: string;
   /** Generated by the Worker after the first answer. */
   title?: string;
   scope: ChatScope;
   /** What the chat was opened on, e.g. `orders.revenue`. */
   subject: string;
   createdAt: number;
   updatedAt: number;
   messages: UIMessage[];
}

const KEY = "console-ai:chats";
const MAX_THREADS = 40;
const listeners = new Set<() => void>();
let cache: { raw: string | null; threads: ChatThread[] } | undefined;

function read(): ChatThread[] {
   const raw = localStorage.getItem(KEY);
   if (cache?.raw === raw) return cache.threads;
   let threads: ChatThread[] = [];
   try {
      threads = raw ? (JSON.parse(raw) as ChatThread[]) : [];
   } catch {
      // A corrupt entry is dropped on the next write.
   }
   cache = { raw, threads };
   return threads;
}

function write(threads: ChatThread[]) {
   let kept = [...threads]
      .sort((a, b) => b.updatedAt - a.updatedAt)
      .slice(0, MAX_THREADS);
   // Tool output makes threads large; drop the oldest until the quota fits.
   while (kept.length) {
      try {
         localStorage.setItem(KEY, JSON.stringify(kept));
         break;
      } catch {
         kept = kept.slice(0, -1);
      }
   }
   if (!kept.length) localStorage.removeItem(KEY);
   listeners.forEach((l) => l());
}

function subscribe(listener: () => void) {
   listeners.add(listener);
   const onStorage = (e: StorageEvent) => e.key === KEY && listener();
   window.addEventListener("storage", onStorage);
   return () => {
      listeners.delete(listener);
      window.removeEventListener("storage", onStorage);
   };
}

/** Saved threads, most recently used first. */
export function useChatThreads(): ChatThread[] {
   return useSyncExternalStore(subscribe, read);
}

export function getThread(id: string): ChatThread | undefined {
   return read().find((t) => t.id === id);
}

export function saveThread(
   id: string,
   update: Partial<ChatThread> &
      Pick<ChatThread, "scope" | "subject"> & { touch?: boolean },
) {
   const { touch = true, ...fields } = update;
   const threads = read();
   const existing = threads.find((t) => t.id === id);
   const now = Date.now();
   const next: ChatThread = {
      messages: [],
      createdAt: now,
      ...existing,
      ...fields,
      id,
      updatedAt: touch || !existing ? now : existing.updatedAt,
   };
   write([next, ...threads.filter((t) => t.id !== id)]);
}

export function deleteThread(id: string) {
   write(read().filter((t) => t.id !== id));
}

export function firstQuestion(messages: UIMessage[]): string | undefined {
   const first = messages.find((m) => m.role === "user");
   const text = first?.parts
      .map((p) => (p.type === "text" ? p.content : ""))
      .join("")
      .trim();
   return text || undefined;
}

/** The generated title, or the opening question until one arrives. */
export function threadTitle(thread: ChatThread | undefined): string {
   if (thread?.title) return thread.title;
   const question = thread && firstQuestion(thread.messages);
   if (!question) return "New chat";
   return question.length > 60 ? `${question.slice(0, 57)}…` : question;
}
